"""obsd.http_app - stdlib ThreadingHTTPServer JSON API."""

from __future__ import annotations

import json
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

from .alerts import AlertEngine
from .tsdb import ObsError, SeriesStore, parse_matchers_text

__all__ = ["ObsdHTTPServer", "create_server", "make_handler", "run_server"]

# Role ranks and the capability each endpoint needs: a viewer reads, a writer
# also writes within its tenant scope, an admin does everything including
# cross-tenant operations.
_ROLE_RANK = {"viewer": 1, "writer": 2, "admin": 3}
_CAPABILITY_RANK = {"read": 1, "write": 2, "admin": 3}


def _int(value, field, default=None):
    if value is None or value == "":
        return default
    try:
        return int(value)
    except (TypeError, ValueError):
        raise ObsError("%s must be an integer" % field)
def _float(value, field):
    try:
        return float(value)
    except (TypeError, ValueError):
        raise ObsError("%s must be a number" % field)
def _require(payload, key):
    if payload.get(key) is None:
        raise ObsError("missing field: %s" % key)
    return payload[key]
def _only(payload, keys):
    """Reject any field outside ``keys`` (a typo must not pass silently)."""
    for key in payload:
        if key not in keys:
            raise ObsError("unexpected field: %s" % key)
def _labels(payload):
    value = payload.get("labels") or {}
    if not isinstance(value, dict):
        raise ObsError("labels must be an object")
    return value
def _group_by(value):
    """``group_by`` arrives as a JSON array of label keys, or is absent."""
    if value is None or value == "":
        return None
    try:
        return json.loads(value)
    except ValueError:
        raise ObsError("group_by must be a JSON array of label keys")
def _tenant_set(value):
    return {value} if isinstance(value, str) and value else set()
def _scope_tenant(value):
    return value if isinstance(value, str) and value else None
def _batch_scope(payload):
    """Per-entry tenants of a batch write; ``set()`` when not determinable."""
    entries = payload.get("entries")
    if isinstance(entries, list) and entries and all(
            isinstance(entry, dict) for entry in entries):
        return set().union(*(_tenant_set(entry.get("tenant")) for entry in entries))
    return set()
def _resource_tenant(rows, key, row_id):
    """Tenant of one stored resource, or ``None`` when it does not exist."""
    for row in rows:
        if row.get("id") == row_id:
            return row.get("tenant")
    return None
def _request_scope(engine, method, path, params, payload):
    """Classify one request as ``(capability, tenants, audit_tenant)``.

    ``tenants`` is ``None`` when no tenant check applies (the capability alone
    decides); otherwise it is the set of tenants the principal must cover. An
    empty set means the request has no single tenant — a cross-tenant
    operation only an admin may run. ``audit_tenant`` is the single tenant to
    record, or ``None``.
    """
    if method == "GET":
        if path in ("/v1/query", "/v1/export"):
            return "read", _tenant_set(params.get("tenant")), params.get("tenant")
        if path in ("/v1/rules", "/v1/notification-routes", "/v1/notifications",
                    "/v1/alerts", "/v1/slos", "/v1/slos/status"):
            return "read", _tenant_set(params.get("tenant")), params.get("tenant")
        if path == "/v1/retention/policies":
            return "read", _tenant_set(params.get("tenant")), params.get("tenant")
        if path in ("/v1/quotas", "/v1/stats", "/v1/audit"):
            return "admin", None, None
    elif method == "POST":
        if path == "/v1/series":
            return "write", _tenant_set(payload.get("tenant")), \
                _scope_tenant(payload.get("tenant"))
        if path == "/v1/series/batch":
            tenants = _batch_scope(payload)
            return "write", tenants, next(iter(tenants)) if len(tenants) == 1 else None
        if path == "/v1/replay":
            # Same per-entry tenant scoping as a batch write: any entry outside
            # the caller's scope rejects the whole replay with 403.
            tenants = _batch_scope(payload)
            return "write", tenants, next(iter(tenants)) if len(tenants) == 1 else None
        if path in ("/v1/rules", "/v1/notification-routes", "/v1/silences",
                    "/v1/slos"):
            return "write", _tenant_set(payload.get("tenant")), \
                _scope_tenant(payload.get("tenant"))
        if path == "/v1/retention/policies":
            return "write", _tenant_set(payload.get("tenant")), \
                _scope_tenant(payload.get("tenant"))
        if path == "/v1/retention/run":
            # With a tenant it is an ordinary tenant-scoped write; without one
            # it sweeps every configured tenant — a cross-tenant operation
            # only an admin may run (an empty scope set permits admins only).
            tenant = payload.get("tenant")
            return ("write", _tenant_set(tenant), _scope_tenant(tenant)) \
                if tenant is not None else ("write", set(), None)
        if path in ("/v1/quotas", "/v1/inhibitions", "/v1/evaluate"):
            return "admin", None, None
        if path.startswith("/v1/notifications/") and path.endswith("/ack"):
            row_id = path[len("/v1/notifications/"):-len("/ack")]
            tenant = _resource_tenant(engine.list_notifications(), "id", row_id)
            # An unknown notification keeps the business 404; only a real one
            # is checked against the caller's scope.
            return ("write", _tenant_set(tenant), tenant) if tenant is not None \
                else ("write", None, None)
    elif method == "DELETE":
        if path.startswith("/v1/rules/"):
            tenant = _resource_tenant(engine.list_rules(), "id", path.rsplit("/", 1)[-1])
            return ("write", _tenant_set(tenant), tenant) if tenant is not None \
                else ("write", None, None)
        if path.startswith("/v1/notification-routes/"):
            tenant = _resource_tenant(engine.list_routes(), "id", path.rsplit("/", 1)[-1])
            return ("write", _tenant_set(tenant), tenant) if tenant is not None \
                else ("write", None, None)
    # Unknown paths carry no tenant scope; dispatch answers 404.
    return "read", None, None
def _permitted(principal, capability, tenants):
    """True when ``principal``'s role covers ``capability`` and ``tenants``."""
    if _ROLE_RANK.get(principal["role"], 0) < _CAPABILITY_RANK[capability]:
        return False
    if principal["role"] == "admin" or tenants is None:
        return True
    return bool(tenants) and all(tenant in principal["tenants"] for tenant in tenants)
def dispatch(store, engine, method, path, params, payload, access=None):
    """Pure routing: (status, body) or ObsError. No sockets involved."""
    labels = {key[6:]: value for key, value in params.items() if key.startswith("label.")}
    if (method, path) == ("GET", "/healthz"):
        return 200, {"ok": True}
    if (method, path) == ("GET", "/v1/stats"):
        return 200, {"store": store.stats(), "alerts": len(engine.list_alerts())}
    if (method, path) == ("GET", "/v1/audit"):
        entries = [] if access is None else access.query_audit(
            tenant=params.get("tenant"), principal_id=params.get("principal_id"),
            outcome=params.get("outcome"),
            after_seq=_int(params.get("after_seq"), "after_seq"),
            limit=_int(params.get("limit"), "limit"))
        return 200, {"entries": entries}
    if (method, path) == ("POST", "/v1/quotas"):
        # Omitted limits default to unlimited; the store validates tenant and
        # limits and raises ObsError (-> 400) without touching the config.
        return 200, store.set_quota(_require(payload, "tenant"),
                                    payload.get("max_series"),
                                    payload.get("max_points"))
    if (method, path) == ("GET", "/v1/quotas"):
        return 200, store.get_quota(_require(params, "tenant"))
    if (method, path) == ("POST", "/v1/retention/policies"):
        # An omitted retention_ms means null (no cleanup); the store validates
        # the tenant and the policy and raises ObsError (-> 400) without
        # touching the persisted config.
        _only(payload, {"tenant", "retention_ms"})
        return 200, store.set_retention(_require(payload, "tenant"),
                                        payload.get("retention_ms"))
    if (method, path) == ("GET", "/v1/retention/policies"):
        return 200, store.get_retention(_require(params, "tenant"))
    if (method, path) == ("POST", "/v1/retention/run"):
        # ``dry_run`` passes through uncoerced: the store accepts only real
        # booleans, just like ``now_ms`` accepts only non-bool integers.
        _only(payload, {"tenant", "now_ms", "dry_run"})
        return 200, store.run_retention(_require(payload, "now_ms"),
                                        tenant=payload.get("tenant"),
                                        dry_run=payload.get("dry_run", False))
    if (method, path) == ("POST", "/v1/series"):
        result = store.write(_require(payload, "tenant"), _require(payload, "metric"),
                             _labels(payload), _require(payload, "samples"),
                             now=payload.get("now_ms"),
                             overwrite=bool(payload.get("overwrite", False)))
        return 202, {"written": result["written"], "duplicates": result["duplicates"],
                     "series_id": result["series_id"]}
    if (method, path) == ("POST", "/v1/series/batch"):
        # ``overwrite`` is passed through uncoerced: the store accepts only
        # real booleans, just like ``now_ms`` accepts only non-bool integers.
        result = store.write_batch(_require(payload, "entries"),
                                   now=payload.get("now_ms"),
                                   overwrite=payload.get("overwrite", False))
        return 202, {"written": result["written"], "duplicates": result["duplicates"],
                     "results": result["results"]}
    if (method, path) == ("POST", "/v1/replay"):
        # The snapshot travels in the body together with the replay options;
        # ``overwrite``/``dry_run`` pass through uncoerced (booleans only).
        snapshot = {key: payload[key]
                    for key in ("version", "snapshot_id", "entries") if key in payload}
        result = store.replay_snapshot(snapshot, now_ms=payload.get("now_ms"),
                                       overwrite=payload.get("overwrite", False),
                                       dry_run=payload.get("dry_run", False))
        return (202 if result["applied"] else 200), result
    if (method, path) == ("GET", "/v1/query"):
        rows = store.query(_require(params, "tenant"), _require(params, "metric"), labels=labels,
                           start_ms=_int(params.get("start"), "start"),
                           end_ms=_int(params.get("end"), "end"),
                           step_ms=_int(params.get("step"), "step"),
                           agg=params.get("agg") or None,
                           group_by=_group_by(params.get("group_by")),
                           window_ms=_int(params.get("window"), "window"),
                           matchers=parse_matchers_text(params.get("matchers")))
        return 200, {"series": [{"labels": row["labels"], "points": row["points"]}
                                for row in rows]}
    if (method, path) == ("GET", "/v1/export"):
        return 200, store.export_snapshot(
            _require(params, "tenant"), _require(params, "metric"), labels=labels,
            start_ms=_int(params.get("start"), "start"),
            end_ms=_int(params.get("end"), "end"),
            matchers=parse_matchers_text(params.get("matchers")))
    if (method, path) == ("POST", "/v1/rules"):
        return 201, engine.add_rule(payload)
    if (method, path) == ("GET", "/v1/rules"):
        return 200, {"rules": engine.list_rules(params.get("tenant"))}
    if (method, path) == ("POST", "/v1/notification-routes"):
        return 201, engine.add_route(payload)
    if (method, path) == ("GET", "/v1/notification-routes"):
        return 200, {"routes": engine.list_routes(params.get("tenant"))}
    if (method, path) == ("GET", "/v1/notifications"):
        acked = params.get("acked")
        if acked is not None:
            if acked not in ("true", "false"):
                raise ObsError("acked must be true or false")
            acked = acked == "true"
        return 200, {"notifications": engine.list_notifications(
            tenant=params.get("tenant"), route_id=params.get("route_id"),
            alert_id=params.get("alert_id"), acked=acked)}
    if method == "POST" and path.startswith("/v1/notifications/") \
            and path.endswith("/ack"):
        return 200, engine.ack_notification(
            path[len("/v1/notifications/"):-len("/ack")])
    if (method, path) == ("POST", "/v1/evaluate"):
        return 200, engine.evaluate(_int(_require(payload, "now_ms"), "now_ms"))
    if (method, path) == ("GET", "/v1/alerts"):
        return 200, {"alerts": engine.list_alerts(params.get("tenant"), params.get("state"))}
    if (method, path) == ("POST", "/v1/silences"):
        return 201, engine.add_silence(_require(payload, "tenant"), _labels(payload),
                                       _require(payload, "starts_ms"),
                                       _require(payload, "ends_ms"), payload.get("reason", ""))
    if (method, path) == ("POST", "/v1/inhibitions"):
        return 201, engine.add_inhibition(_require(payload, "source_severity"),
                                          _require(payload, "target_severity"),
                                          bool(payload.get("same_labels", True)))
    if (method, path) == ("POST", "/v1/slos"):
        return 201, engine.set_slo(_require(payload, "tenant"), _require(payload, "name"),
                                   _require(payload, "metric"), _labels(payload),
                                   _require(payload, "good_comparator"),
                                   _float(_require(payload, "threshold"), "threshold"),
                                   _float(_require(payload, "target_ratio"), "target_ratio"),
                                   _require(payload, "window_ms"))
    if (method, path) == ("GET", "/v1/slos"):
        return 200, {"slos": engine.list_slos(params.get("tenant"))}
    if (method, path) == ("GET", "/v1/slos/status"):
        now = _int(params.get("now_ms"), "now_ms", int(time.time() * 1000))
        return 200, engine.slo_status(_require(params, "name"), now, tenant=params.get("tenant"))
    raise ObsError("not found: %s %s" % (method, path))
def _status_for(message):
    if message.startswith("not found"):
        return 404
    # Unknown rules/alerts/SLOs/comparators are missing resources (404); an
    # unknown aggregation is a malformed request (400).
    if message.startswith("unknown") and not message.startswith("unknown aggregation"):
        return 404
    return 409 if message.startswith(("conflict", "quota exceeded")) else 400
def make_handler(store, engine, access=None):
    class ObsdHandler(BaseHTTPRequestHandler):
        server_version = "obsd/0.1"
        sys_version = ""
        protocol_version = "HTTP/1.1"

        def log_message(self, fmt, *args):
            """Keep stdout clean: every line printed is a JSON payload."""
        def _read_json(self):
            length = _int(self.headers.get("Content-Length"), "Content-Length", 0) or 0
            if not length:
                return {}
            try:
                payload = json.loads(self.rfile.read(length).decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                raise ObsError("invalid JSON body")
            if not isinstance(payload, dict):
                raise ObsError("JSON body must be an object")
            return payload
        def _send(self, status, body):
            data = json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def _bearer_token(self):
            """The token of ``Authorization: Bearer <token>``, else ``None``."""
            header = self.headers.get("Authorization")
            if not header:
                return None
            parts = header.split()
            if len(parts) != 2 or parts[0] != "Bearer":
                return None
            return parts[1]
        def _handle(self, method, call):
            parsed = urlparse(self.path)
            params = {key: values[-1] for key, values in parse_qs(parsed.query).items()}
            # Blank values are dropped like every other parameter, except an
            # explicit empty matchers is an illegal value rather than omission.
            blank_params = parse_qs(parsed.query, keep_blank_values=True)
            if "matchers" in blank_params:
                params["matchers"] = blank_params["matchers"][-1]
            # /healthz is always public and never audited. While no access
            # config exists every request stays anonymous and unaudited.
            guarded = access is not None and parsed.path != "/healthz"
            if guarded:
                access.refresh()
                guarded = access.enabled()
            principal = None
            audit_tenant = params.get("tenant")
            if guarded:
                principal = access.authenticate(self._bearer_token())
                if principal is None:
                    self._send(401, {"error": "unauthorized"})
                    access.record(None, method, parsed.path, audit_tenant,
                                  "denied", 401)
                    return
            try:
                payload = self._read_json() if method == "POST" else {}
            except ObsError as exc:
                status = _status_for(str(exc))
                self._send(status, {"error": str(exc)})
                if guarded:
                    access.record(principal["id"], method, parsed.path,
                                  audit_tenant, "failed", status)
                return
            if guarded:
                capability, tenants, audit_tenant = _request_scope(
                    engine, method, parsed.path, params, payload)
                if not _permitted(principal, capability, tenants):
                    self._send(403, {"error": "forbidden"})
                    access.record(principal["id"], method, parsed.path,
                                  audit_tenant, "denied", 403)
                    return
            try:
                status, body = call(parsed.path, params, payload)
            except ObsError as exc:
                status, body = _status_for(str(exc)), {"error": str(exc)}
            except Exception as exc:  # pragma: no cover - defensive
                status, body = 500, {"error": "internal error: %s" % exc}
            self._send(status, body)
            if guarded:
                access.record(principal["id"], method, parsed.path, audit_tenant,
                              "allowed" if status < 400 else "failed", status)
        def do_GET(self):
            self._handle("GET", lambda path, params, payload:
                         dispatch(store, engine, "GET", path, params, payload,
                                  access=access))
        def do_POST(self):
            self._handle("POST", lambda path, params, payload:
                         dispatch(store, engine, "POST", path, params, payload,
                                  access=access))
        def do_DELETE(self):
            def call(path, params, payload):
                if path.startswith("/v1/rules/"):
                    return 200, engine.del_rule(path.rsplit("/", 1)[-1])
                if path.startswith("/v1/notification-routes/"):
                    return 200, engine.del_route(path.rsplit("/", 1)[-1])
                raise ObsError("not found: DELETE %s" % path)
            self._handle("DELETE", call)
    return ObsdHandler
class ObsdHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address, store, engine, access=None):
        self.store = store
        self.engine = engine
        self.access = access
        super().__init__(address, make_handler(store, engine, access))
def create_server(store, engine, host="127.0.0.1", port=8080, access=None):
    """Build (but do not start) a ThreadingHTTPServer bound to ``host:port``."""
    if not isinstance(store, SeriesStore):
        raise ObsError("store must be a SeriesStore")
    if not isinstance(engine, AlertEngine):
        raise ObsError("engine must be an AlertEngine")
    return ObsdHTTPServer((host, int(port)), store, engine, access)
def run_server(store, engine, host="127.0.0.1", port=8080, access=None):
    """Serve until interrupted; prints one JSON startup line on stdout."""
    server = create_server(store, engine, host, port, access=access)
    print(json.dumps({"ok": True, "listening": "http://%s:%d" % server.server_address[:2],
                      "data_dir": store.root}, sort_keys=True, separators=(",", ":")), flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0

"""obsd.tsdb - series identity, idempotent writes, bucketed query, retention.

Standard library only. All logic takes an explicit clock (``now``) where time
matters; nothing here calls time.time().
"""

from __future__ import annotations

import hashlib
import json
import math
import os
import re
import threading

__all__ = ["ObsError", "SeriesStore", "AGGREGATES", "COUNTER_AGGREGATES",
           "canonical_identity", "series_id_for"]

AGGREGATES = ("sum", "avg", "min", "max", "count")
# Sliding-window-only counter aggregates: accepted by ``SeriesStore.query``
# (and the HTTP/CLI query entries built on it) when ``window_ms`` is given.
# Rollup, alert rules and SLOs keep validating against ``AGGREGATES`` alone.
COUNTER_AGGREGATES = ("increase", "rate")
MATCHER_OPS = ("=", "!=", "=~", "!~")


class ObsError(Exception):
    """Raised for any rejected observation or request."""


def _num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _labels_list(labels):
    """Normalise labels to a list of ``[key, value]`` pairs sorted by key."""
    if labels is None:
        return []
    if isinstance(labels, dict):
        items = list(labels.items())
    elif isinstance(labels, (list, tuple)):
        items = []
        for entry in labels:
            if not isinstance(entry, (list, tuple)) or len(entry) != 2:
                raise ObsError("labels entries must be [key, value] pairs")
            items.append((entry[0], entry[1]))
    else:
        raise ObsError("labels must be an object or a list of pairs")
    pairs = []
    for key, value in items:
        if not isinstance(key, str) or value is None:
            raise ObsError("label keys must be strings and values must not be null")
        pairs.append([key, str(value)])
    pairs.sort(key=lambda pair: pair[0])
    if len({key for key, _ in pairs}) != len(pairs):
        raise ObsError("duplicate label key")
    return pairs


def as_labels(labels):
    """Normalise labels to a plain dict."""
    return {key: value for key, value in _labels_list(labels)}


def canonical_identity(tenant, metric, labels):
    """Canonical newline-joined identity string of a series."""
    if not isinstance(tenant, str) or not tenant:
        raise ObsError("tenant must be a non-empty string")
    if not isinstance(metric, str) or not metric:
        raise ObsError("metric must be a non-empty string")
    return "\n".join([tenant, metric] +
                     ["%s=%s" % (key, value) for key, value in _labels_list(labels)])


def series_id_for(tenant, metric, labels):
    """64-char sha256 id of a series, independent of label insertion order."""
    return hashlib.sha256(canonical_identity(tenant, metric, labels).encode("utf-8")).hexdigest()


def matches_labels(series_labels, matcher):
    """True when every matcher pair is present in ``series_labels``."""
    if not matcher:
        return True
    if isinstance(matcher, (list, tuple)):
        matcher = as_labels(matcher)
    return all(str(series_labels.get(key)) == str(value) for key, value in matcher.items())


def compile_matchers(matchers):
    """Validate ``matchers`` and return ``(key, op, value, pattern)`` tuples.

    Each element is an object with exactly ``key`` (non-empty string), ``op``
    (one of ``=``, ``!=``, ``=~``, ``!~``) and ``value`` (string, possibly
    empty). ``None`` and an empty list add no condition; regex patterns are
    compiled here, so an invalid pattern is rejected before any series is read.
    """
    if matchers is None:
        return ()
    if not isinstance(matchers, (list, tuple)):
        raise ObsError("matchers must be a list of matcher objects")
    compiled = []
    for element in matchers:
        if not isinstance(element, dict):
            raise ObsError("each matcher must be an object with key, op and value")
        if set(element) != {"key", "op", "value"}:
            raise ObsError("each matcher must contain exactly key, op and value")
        key, op, value = element["key"], element["op"], element["value"]
        if not isinstance(key, str) or not key:
            raise ObsError("matcher key must be a non-empty string")
        if op not in MATCHER_OPS:
            raise ObsError("matcher op must be one of %s" % (MATCHER_OPS,))
        if not isinstance(value, str):
            raise ObsError("matcher value must be a string")
        pattern = None
        if op in ("=~", "!~"):
            try:
                pattern = re.compile(value)
            except re.error as exc:
                raise ObsError("invalid matcher regex %r: %s" % (value, exc))
        compiled.append((key, op, value, pattern))
    return tuple(compiled)


def matchers_hold(series_labels, compiled):
    """True when every compiled matcher holds for ``series_labels``.

    A missing key never satisfies ``=``/``=~`` but always satisfies ``!=``/
    ``!~``; regex matchers anchor with ``fullmatch`` so the pattern covers the
    whole value. Only real labels are considered.
    """
    for key, op, value, pattern in compiled:
        present = key in series_labels
        if op == "=":
            if not present or series_labels[key] != value:
                return False
        elif op == "!=":
            if present and series_labels[key] == value:
                return False
        elif op == "=~":
            if not present or pattern.fullmatch(series_labels[key]) is None:
                return False
        else:  # "!~"
            if present and pattern.fullmatch(series_labels[key]) is not None:
                return False
    return True


def parse_matchers_text(text, field="matchers"):
    """Decode a JSON array text of matcher objects; ``None``/absent adds none.

    Used by the HTTP and CLI entry points, where the parameter arrives as a
    string. Returns the raw decoded list (validated later by
    :func:`compile_matchers`, which runs even with no candidate series). Empty
    text and an explicit JSON ``null`` are illegal here (unlike omitting the
    parameter or passing Python ``None`` to ``query``).
    """
    if text is None:
        return None
    if not isinstance(text, str) or not text:
        raise ObsError("%s must be a JSON array of matcher objects" % field)
    try:
        data = json.loads(text)
    except ValueError:
        raise ObsError("%s must be a JSON array of matcher objects" % field)
    if data is None:
        raise ObsError("%s must be a JSON array of matcher objects" % field)
    if not isinstance(data, list):
        raise ObsError("%s must be a JSON array of matcher objects" % field)
    return data


def _clean_samples(samples, now):
    """Validate ``samples`` against the optional clock; return clean pairs.

    Shared by ``SeriesStore.write`` and ``SeriesStore.write_batch`` so single
    and multi-series writes apply exactly the same sample rules.
    """
    if not isinstance(samples, (list, tuple)):
        raise ObsError("samples must be a list of [timestamp_ms, value] pairs")
    clean = []
    for entry in samples:
        if not isinstance(entry, (list, tuple)) or len(entry) != 2:
            raise ObsError("each sample must be a [timestamp_ms, value] pair")
        stamp, value = entry
        if not _num(stamp) or not _num(value):
            raise ObsError("sample timestamp and value must be numbers")
        if now is not None and int(stamp) > int(now):
            raise ObsError("sample timestamp %d is in the future (now=%d)"
                           % (int(stamp), int(now)))
        clean.append((int(stamp), float(value)))
    if not clean:
        raise ObsError("samples must not be empty")
    return clean


def _aggregate(values, agg):
    if agg == "sum":
        return float(sum(values))
    if agg == "avg":
        return sum(values) / float(len(values))
    if agg == "min":
        return float(min(values))
    if agg == "max":
        return float(max(values))
    if agg == "count":
        return len(values)
    raise ObsError("unknown aggregation: %r" % (agg,))


def _atomic_write(path, text):
    """Write ``text`` to ``path`` through a temp file plus os.replace."""
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(path + ".tmp", "w", encoding="utf-8") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(path + ".tmp", path)


def _line(stamp, value):
    return json.dumps({"t": stamp, "v": value}, separators=(",", ":")) + "\n"


def _snapshot_bytes(document):
    """Canonical UTF-8 bytes of a snapshot document for its SHA-256 digest."""
    return json.dumps(document, sort_keys=True,
                      separators=(",", ":")).encode("utf-8")


class SeriesStore:
    """Append-mostly time series store persisted under ``root``.

    Layout::

        <root>/series.json                 registry: series_id -> series row
        <root>/points/<series_id>.jsonl    one ``{"t":ts,"v":value}`` per line
        <root>/quotas.json                 tenant -> {"max_series", "max_points"}
        <root>/retention.json              tenant -> {"retention_ms"}
    """

    def __init__(self, root):
        if not isinstance(root, (str, os.PathLike)) or not str(root):
            raise ObsError("root must be a non-empty path")
        self.root = os.path.abspath(str(root))
        self.points_dir = os.path.join(self.root, "points")
        self.series_path = os.path.join(self.root, "series.json")
        self.quota_path = os.path.join(self.root, "quotas.json")
        self.retention_path = os.path.join(self.root, "retention.json")
        self._lock = threading.RLock()
        self._series, self._samples, self._writes = {}, {}, 0
        self._quotas = {}
        self._retention = {}
        os.makedirs(self.points_dir, exist_ok=True)
        self._load()
        self._load_quotas()
        self._load_retention()

    def _points_path(self, sid):
        return os.path.join(self.points_dir, sid + ".jsonl")

    # ------------------------------------------------------------- persistence
    def _load(self):
        rows = []
        if os.path.exists(self.series_path):
            try:
                with open(self.series_path, "r", encoding="utf-8") as handle:
                    rows = json.load(handle)
            except (OSError, ValueError) as exc:
                raise ObsError("cannot read series registry: %s" % exc)
        for row in rows:
            sid = row.get("series_id")
            if not sid:
                continue
            self._series[sid] = {"series_id": sid, "tenant": row.get("tenant"),
                                 "metric": row.get("metric"),
                                 "labels": [[str(k), str(v)] for k, v in row.get("labels", [])],
                                 "identity": row.get("identity")}
            self._samples[sid] = self._read_points(sid)

    def _read_points(self, sid):
        """Reload one point file, skipping unreadable lines.

        Repeated lines for the same timestamp (left behind by historical
        overwrites) collapse to the last value stored, so occupancy counts each
        distinct timestamp once after a reopen.
        """
        rows = {}
        path = self._points_path(sid)
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                        rows[int(row["t"])] = float(row["v"])
                    except (ValueError, KeyError, TypeError):
                        continue
        return sorted(rows.items())

    def _save_registry(self):
        _atomic_write(self.series_path, json.dumps(
            [self._series[sid] for sid in sorted(self._series)],
            sort_keys=True, separators=(",", ":")))

    def _rewrite_points(self, sid):
        _atomic_write(self._points_path(sid),
                      "".join(_line(ts, value) for ts, value in self._samples[sid]))

    # ------------------------------------------------------------------ quotas
    def _load_quotas(self):
        """Reload ``quotas.json``; a missing file means every tenant is unlimited."""
        if not os.path.exists(self.quota_path):
            return
        try:
            with open(self.quota_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, ValueError) as exc:
            raise ObsError("cannot read quota config: %s" % exc)
        if not isinstance(data, dict):
            raise ObsError("cannot read quota config: root must be an object")
        for tenant, row in data.items():
            if not isinstance(tenant, str) or not tenant or not isinstance(row, dict):
                raise ObsError("cannot read quota config: malformed entry")
            self._quotas[tenant] = {
                "max_series": self._clean_limit(row.get("max_series"), "max_series"),
                "max_points": self._clean_limit(row.get("max_points"), "max_points")}

    @staticmethod
    def _clean_limit(value, field):
        """A limit is a non-negative integer or ``None`` (unlimited)."""
        if value is None:
            return None
        if isinstance(value, bool) or not isinstance(value, int):
            raise ObsError("%s must be a non-negative integer or null" % field)
        if value < 0:
            raise ObsError("%s must be a non-negative integer or null" % field)
        return value

    @staticmethod
    def _clean_tenant(tenant):
        if not isinstance(tenant, str) or not tenant:
            raise ObsError("tenant must be a non-empty string")
        return tenant

    def _save_quotas(self):
        _atomic_write(self.quota_path, json.dumps(
            {tenant: self._quotas[tenant] for tenant in sorted(self._quotas)},
            sort_keys=True, separators=(",", ":")))

    def set_quota(self, tenant, max_series, max_points):
        """Configure the per-tenant limits; ``None`` means unlimited.

        Limits may be lowered below current usage; pure duplicate/overwrite
        writes stay allowed afterwards. Configuring a quota never creates a
        series.
        """
        tenant = self._clean_tenant(tenant)
        max_series = self._clean_limit(max_series, "max_series")
        max_points = self._clean_limit(max_points, "max_points")
        with self._lock:
            self._quotas[tenant] = {"max_series": max_series, "max_points": max_points}
            self._save_quotas()
            return self.get_quota(tenant)

    def get_quota(self, tenant):
        """Return limits and current usage for ``tenant`` in one snapshot."""
        tenant = self._clean_tenant(tenant)
        with self._lock:
            limits = self._quotas.get(tenant, {"max_series": None, "max_points": None})
            series = points = 0
            for sid, row in self._series.items():
                if row["tenant"] == tenant:
                    series += 1
                    points += len(self._samples[sid])
            return {"tenant": tenant, "max_series": limits["max_series"],
                    "max_points": limits["max_points"], "series": series, "points": points}

    # ------------------------------------------------------------------- write
    def write(self, tenant, metric, labels, samples, now=None, overwrite=False):
        """Store ``samples`` = ``[(timestamp_ms, value), ...]``.

        Idempotent: an identical ``(series, timestamp)`` value is a duplicate
        and changes nothing. A differing value for a stored timestamp raises
        ``ObsError`` unless ``overwrite=True``.

        The whole batch is checked against the tenant's configured quotas
        *after* input validation and conflict rules, using the net new series
        and distinct new timestamps the batch would add (same-value replays,
        overwrites and timestamps repeated inside the batch add nothing). A
        batch that would exceed either limit is rejected wholesale with
        ``ObsError``: no series, points or write counter change is kept.
        """
        clean = _clean_samples(samples, now)
        # Labels/tenant are validated before the lock so conflicts and quota
        # breaches never surface as identity errors.
        pairs = _labels_list(labels)
        identity = canonical_identity(tenant, metric, pairs)
        sid = hashlib.sha256(identity.encode("utf-8")).hexdigest()
        with self._lock:
            existed = sid in self._series
            current = dict(self._samples.get(sid, ()))
            merged = dict(current)
            written = duplicates = 0
            new_stamps = set()
            overwritten = False
            for stamp, value in clean:
                if stamp in merged:
                    if merged[stamp] != value:
                        if not overwrite:
                            raise ObsError(
                                "conflict for %s at timestamp %d: stored=%r incoming=%r"
                                % (sid, stamp, merged[stamp], value))
                        if stamp in current:
                            overwritten = True
                    else:
                        duplicates += 1
                        continue
                else:
                    new_stamps.add(stamp)
                merged[stamp] = value
                written += 1

            quota = self._quotas.get(tenant)
            if quota is not None:
                used_series = used_points = 0
                for sid_, row in self._series.items():
                    if row["tenant"] == tenant:
                        used_series += 1
                        used_points += len(self._samples[sid_])
                new_series = 0 if existed else 1
                new_points = len(new_stamps)
                limit_series = quota["max_series"]
                limit_points = quota["max_points"]
                if new_series and limit_series is not None \
                        and used_series + new_series > limit_series:
                    raise ObsError(
                        "quota exceeded for tenant %r: series %d+%d > max_series %s"
                        % (tenant, used_series, new_series, limit_series))
                if new_points and limit_points is not None \
                        and used_points + new_points > limit_points:
                    raise ObsError(
                        "quota exceeded for tenant %r: points %d+%d > max_points %s"
                        % (tenant, used_points, new_points, limit_points))

            if not existed:
                self._series[sid] = {"series_id": sid, "tenant": tenant, "metric": metric,
                                     "labels": pairs, "identity": identity}
                self._samples[sid] = []
            if written:
                self._samples[sid] = sorted(merged.items())
                if overwritten:
                    # An overwrite replaced a stored value: rewrite the file so a
                    # timestamp never occupies more than one physical line.
                    self._rewrite_points(sid)
                else:
                    fresh = sorted((stamp, merged[stamp]) for stamp in new_stamps)
                    with open(self._points_path(sid), "a", encoding="utf-8") as handle:
                        handle.write("".join(_line(ts, value) for ts, value in fresh))
                        handle.flush()
                        os.fsync(handle.fileno())
                self._writes += 1
                self._save_registry()
        return {"series_id": sid, "written": written, "duplicates": duplicates}

    def write_batch(self, entries, now=None, overwrite=False):
        """Atomically store many series' samples in one all-or-nothing batch.

        ``entries`` is a non-empty list of objects, each with exactly the
        required fields ``tenant``, ``metric`` and ``samples`` plus an optional
        ``labels`` (omitted means ``{}``); identity and sample validation are
        the same as :meth:`write`. Entries may span tenants and metrics and
        may repeat a series. ``now`` is ``None`` (no future check) or a
        non-boolean integer; ``overwrite`` must be a boolean.

        The whole batch is validated before any conflict is reported, and all
        conflicts before any quota check. Entries and their samples are then
        applied in input order, so a later entry sees the earlier entries of
        the same batch: a same-value restatement counts as a duplicate, a
        differing value conflicts unless ``overwrite`` (then it replaces and
        counts as written). Quotas are charged per tenant with the batch's net
        new series and distinct new timestamps — duplicates and overwrites add
        no occupancy, and only dimensions that actually increase are checked.

        Any rejection (structure, validation, future sample, conflict, quota)
        raises ``ObsError`` and leaves no series, sample or write-count change
        behind, on disk included. On success ``stats()["writes"]`` increases
        by exactly one when the batch wrote anything; a pure-duplicate batch
        increases nothing. Returns ``{"written", "duplicates", "results"}``
        where ``results`` holds one ``{"series_id", "written", "duplicates"}``
        per entry, in input order, and the totals are their sums.
        """
        return self._apply_batch(entries, now=now, overwrite=overwrite, commit=True)

    def _apply_batch(self, entries, now=None, overwrite=False, commit=True):
        """The ``write_batch`` machinery; ``commit=False`` only validates and counts.

        With ``commit=False`` every check runs exactly as for a real batch
        (structure, samples, future timestamps, conflicts, quotas) and the
        same ``{"written", "duplicates", "results"}`` preview is returned, but
        no series, sample, counter or file ever changes. Used by snapshot
        replay, where a dry run must prove applicable without applying.
        """
        if now is not None and (isinstance(now, bool) or not isinstance(now, int)):
            raise ObsError("now must be a non-boolean integer timestamp in ms or None")
        if not isinstance(overwrite, bool):
            raise ObsError("overwrite must be a boolean")
        if not isinstance(entries, (list, tuple)) or not entries:
            raise ObsError("entries must be a non-empty list of entry objects")
        # Phase 1: validate every entry before any conflict or quota check, so
        # a malformed later entry never masks an earlier conflict.
        prepared = []
        for index, entry in enumerate(entries):
            if not isinstance(entry, dict):
                raise ObsError("entry %d must be an object with tenant, metric "
                               "and samples" % index)
            if set(entry) - {"tenant", "metric", "samples", "labels"}:
                raise ObsError("entry %d must contain only tenant, metric, "
                               "samples and labels" % index)
            for field in ("tenant", "metric", "samples"):
                if entry.get(field) is None:
                    raise ObsError("entry %d: missing field: %s" % (index, field))
            clean = _clean_samples(entry["samples"], now)
            pairs = _labels_list(entry.get("labels"))
            identity = canonical_identity(entry["tenant"], entry["metric"], pairs)
            sid = hashlib.sha256(identity.encode("utf-8")).hexdigest()
            prepared.append((entry["tenant"], entry["metric"], pairs, identity,
                             sid, clean))
        with self._lock:
            # Phase 2: replay the batch in input order against a private copy
            # of the touched series, so later entries see earlier ones.
            originals, merged = {}, {}
            new_stamps, overwritten = {}, {}
            results = []
            total_written = total_duplicates = 0
            for tenant, metric, pairs, identity, sid, clean in prepared:
                if sid not in merged:
                    originals[sid] = dict(self._samples.get(sid, ()))
                    merged[sid] = dict(originals[sid])
                    new_stamps[sid] = set()
                    overwritten[sid] = False
                state, stored = merged[sid], originals[sid]
                written = duplicates = 0
                for stamp, value in clean:
                    if stamp in state:
                        if state[stamp] != value:
                            if not overwrite:
                                raise ObsError(
                                    "conflict for %s at timestamp %d: "
                                    "stored=%r incoming=%r"
                                    % (sid, stamp, state[stamp], value))
                            if stamp in stored:
                                overwritten[sid] = True
                        else:
                            duplicates += 1
                            continue
                    else:
                        new_stamps[sid].add(stamp)
                    state[stamp] = value
                    written += 1
                results.append({"series_id": sid, "written": written,
                                "duplicates": duplicates})
                total_written += written
                total_duplicates += duplicates
            # Phase 3: per-tenant quota check on the batch's net increase.
            tenants = {}
            for tenant, metric, pairs, identity, sid, clean in prepared:
                usage = tenants.setdefault(tenant, {"sids": set(), "points": 0})
                if sid not in usage["sids"]:
                    usage["sids"].add(sid)
                    usage["points"] += len(new_stamps[sid])
            for tenant, usage in tenants.items():
                quota = self._quotas.get(tenant)
                if quota is None:
                    continue
                used_series = used_points = 0
                for sid_, row in self._series.items():
                    if row["tenant"] == tenant:
                        used_series += 1
                        used_points += len(self._samples[sid_])
                new_series = sum(1 for sid in usage["sids"] if sid not in self._series)
                new_points = usage["points"]
                limit_series = quota["max_series"]
                limit_points = quota["max_points"]
                if new_series and limit_series is not None \
                        and used_series + new_series > limit_series:
                    raise ObsError(
                        "quota exceeded for tenant %r: series %d+%d > max_series %s"
                        % (tenant, used_series, new_series, limit_series))
                if new_points and limit_points is not None \
                        and used_points + new_points > limit_points:
                    raise ObsError(
                        "quota exceeded for tenant %r: points %d+%d > max_points %s"
                        % (tenant, used_points, new_points, limit_points))
            # Phase 4: commit. Everything before this point was in-memory
            # simulation, so a rejection above leaves no trace anywhere.
            if commit and total_written:
                committed = set()
                for tenant, metric, pairs, identity, sid, clean in prepared:
                    if sid in committed:
                        continue
                    committed.add(sid)
                    if sid not in self._series:
                        self._series[sid] = {"series_id": sid, "tenant": tenant,
                                             "metric": metric, "labels": pairs,
                                             "identity": identity}
                        self._samples[sid] = []
                    if not new_stamps[sid] and not overwritten[sid]:
                        continue
                    self._samples[sid] = sorted(merged[sid].items())
                    if overwritten[sid]:
                        # A stored value was replaced: rewrite the file so a
                        # timestamp never occupies more than one physical line.
                        self._rewrite_points(sid)
                    else:
                        fresh = sorted((stamp, merged[sid][stamp])
                                       for stamp in new_stamps[sid])
                        with open(self._points_path(sid), "a",
                                  encoding="utf-8") as handle:
                            handle.write("".join(_line(ts, value)
                                                 for ts, value in fresh))
                            handle.flush()
                            os.fsync(handle.fileno())
                self._writes += 1
                self._save_registry()
        return {"written": total_written, "duplicates": total_duplicates,
                "results": results}

    # ------------------------------------------------------------------ export
    def export_snapshot(self, tenant, metric, labels=None, start_ms=None,
                        end_ms=None, matchers=None):
        """A verifiable snapshot of the matching series' raw samples.

        Filters exactly like :meth:`query` (exact ``labels``, ``matchers`` and
        the closed ``[start_ms, end_ms]`` interval) and returns
        ``{"version": 1, "snapshot_id": ..., "entries": [...]}``. Each entry
        holds only ``tenant``, ``metric``, ``labels`` and ``samples`` (the
        in-range samples, ascending by timestamp); entries are ordered by
        ``series_id`` and registered series with no sample in range are
        omitted. ``snapshot_id`` is the SHA-256 of the sorted, compact JSON
        UTF-8 bytes of ``{"version": 1, "entries": [...]}``, so any instance
        can verify a snapshot before replaying it.

        The whole export reads one coherent snapshot under a single lock
        acquisition and never changes series, samples, write counters, quotas,
        alerts or query results: exporting the same state twice yields
        byte-identical content.
        """
        compiled_matchers = compile_matchers(matchers)
        lo = None if start_ms is None else int(start_ms)
        hi = None if end_ms is None else int(end_ms)
        if lo is not None and hi is not None and hi < lo:
            raise ObsError("end_ms must be >= start_ms")
        entries = []
        for sid, series_labels, samples in self._matching_series(
                tenant, metric, labels, compiled_matchers):
            rows = [[stamp, value] for stamp, value in samples
                    if (lo is None or stamp >= lo) and (hi is None or stamp <= hi)]
            if not rows:
                continue
            entries.append({"tenant": tenant, "metric": metric,
                            "labels": series_labels, "samples": rows})
        digest = hashlib.sha256(_snapshot_bytes(
            {"version": 1, "entries": entries})).hexdigest()
        return {"version": 1, "snapshot_id": digest, "entries": entries}

    # ------------------------------------------------------------------ replay
    def replay_snapshot(self, snapshot, now_ms=None, overwrite=False,
                        dry_run=False):
        """Validate and apply a snapshot produced by :meth:`export_snapshot`.

        The snapshot is verified before anything is stored: ``version`` must
        be 1, ``snapshot_id`` must equal the SHA-256 digest of the canonical
        ``{"version": 1, "entries": [...]}`` document, and every entry is then
        checked by the :meth:`write_batch` rules (labels, samples, future
        timestamps against ``now_ms`` when given, conflicts, per-tenant
        quotas) — invalid input or a digest mismatch raises ``ObsError``
        (``400`` semantics), a conflict or quota breach raises ``ObsError``
        (``409`` semantics), and any failure leaves no in-memory or on-disk
        change behind.

        With ``dry_run=True`` all validation and counting runs but nothing is
        applied and the result carries ``applied=False``; otherwise the batch
        commits and ``applied`` is ``True``. The result is ``{"written",
        "duplicates", "results", "applied"}`` with ``results`` in entry order.
        Replaying a snapshot onto the state it was exported from is a pure
        duplicate replay (``written == 0``, the write counter does not move);
        replaying onto a partial state fills in only the missing points. An
        empty ``entries`` list is a valid no-op snapshot.
        """
        if not isinstance(dry_run, bool):
            raise ObsError("dry_run must be a boolean")
        if now_ms is not None and (isinstance(now_ms, bool)
                                   or not isinstance(now_ms, int)):
            raise ObsError("now_ms must be a non-boolean integer timestamp in ms or None")
        if not isinstance(overwrite, bool):
            raise ObsError("overwrite must be a boolean")
        if not isinstance(snapshot, dict):
            raise ObsError("snapshot must be an object with version, "
                           "snapshot_id and entries")
        version = snapshot.get("version")
        if isinstance(version, bool) or version != 1:
            raise ObsError("unsupported snapshot version: %r" % (version,))
        entries = snapshot.get("entries")
        if not isinstance(entries, list):
            raise ObsError("snapshot entries must be a list")
        snapshot_id = snapshot.get("snapshot_id")
        if not isinstance(snapshot_id, str) or not snapshot_id:
            raise ObsError("snapshot_id must be a non-empty string")
        digest = hashlib.sha256(_snapshot_bytes(
            {"version": 1, "entries": entries})).hexdigest()
        if snapshot_id != digest:
            raise ObsError("snapshot_id does not match the entries digest")
        if not entries:
            return {"written": 0, "duplicates": 0, "results": [],
                    "applied": not dry_run}
        result = self._apply_batch(entries, now=now_ms, overwrite=overwrite,
                                   commit=not dry_run)
        return {"written": result["written"], "duplicates": result["duplicates"],
                "results": result["results"], "applied": not dry_run}

    # ------------------------------------------------------------------- query
    def _matching_series(self, tenant, metric, labels, compiled_matchers=()):
        """Snapshot of every matching series: sid, labels and raw samples.

        Copied under one lock acquisition so a query can never mix samples from
        before and after a concurrent write or retention sweep. Exact ``labels``
        and the compiled ``matchers`` both filter the same raw series labels
        before any aggregation or grouping takes place.
        """
        with self._lock:
            ids = sorted(sid for sid, row in self._series.items()
                         if row["tenant"] == tenant and row["metric"] == metric
                         and matches_labels(dict(row["labels"]), labels)
                         and matchers_hold(dict(row["labels"]), compiled_matchers))
            return [(sid, dict(self._series[sid]["labels"]), list(self._samples[sid]))
                    for sid in ids]

    def _samples_for(self, tenant, metric, labels, compiled_matchers=()):
        return [(sid, samples) for sid, _, samples in
                self._matching_series(tenant, metric, labels, compiled_matchers)]

    def _scan(self, tenant, metric, labels, start_ms, end_ms):
        """Raw samples of matching series inside ``[start, end]`` (internal).

        Used where exact event counts matter (SLO numerator/denominator) and by
        rule evaluation to find candidate series.
        """
        lo = None if start_ms is None else int(start_ms)
        hi = None if end_ms is None else int(end_ms)
        out = []
        for sid, samples in self._samples_for(tenant, metric, labels):
            rows = [item for item in samples
                    if (lo is None or item[0] >= lo) and (hi is None or item[0] <= hi)]
            if rows:
                out.append((sid, rows))
        return out

    def query(self, tenant, metric, labels=None, start_ms=None, end_ms=None,
              step_ms=None, agg=None, group_by=None, window_ms=None, matchers=None):
        """Raw, bucketed or sliding-window points per matching series.

        ``matchers`` is an optional list of ``{"key", "op", "value"}`` objects
        (``None`` or ``[]`` adds no condition). Supported ops: ``=``, ``!=``
        (exact whole-string equality/negation), ``=~``, ``!~`` (Python ``re``
        full-match/negation, case-sensitive, Unicode-aware). Matchers combine
        with each other and with ``labels`` by logical AND, apply to the raw
        series labels before bucketing/grouping (keys absent from
        ``group_by`` included), and are validated up front even when no series
        could match. A missing key fails ``=``/``=~`` and passes ``!=``/``!~``.

        ``step_ms`` buckets are left-closed/right-open on epoch multiples and
        empty buckets are emitted as ``None``. A series with no sample in range
        is still listed, with an empty ``points`` list, unless ``agg`` is used
        without ``step_ms`` (then it yields nothing and is omitted).

        ``group_by=None`` keeps this per-series behaviour. Otherwise it must
        be a list of distinct non-empty label keys (``[]`` merges every match
        into one group) and ``agg`` is required: the raw in-range samples of
        all series in a group are aggregated together and each result row
        carries only ``labels`` (the group keys present on those series) and
        ``points``.

        With ``window_ms`` the query switches to sliding-window mode: it
        requires ``start_ms``, ``end_ms``, ``step_ms`` and ``agg``, all integer
        milliseconds (step and window strictly positive). Evaluation times are
        ``start_ms + k*step_ms`` not exceeding ``end_ms``; the point timestamp
        is the evaluation time and its value aggregates the raw samples in
        ``(t - window_ms, t]`` (left edge excluded, right edge included). The
        first window reads history before ``start_ms``, but never anything past
        ``t``. Empty windows, including ``count``, emit ``None``. Every matching
        series (or group) gets the full time grid even when every window is
        empty; no matching series yields an empty list.

        ``agg`` may also be ``increase`` or ``rate`` (sliding-window mode only;
        without ``window_ms`` they are rejected). These treat each matching
        series as a counter: per window, adjacent in-window readings contribute
        their difference when non-decreasing, and a drop is treated as a
        counter reset contributing only the later reading (the first reading
        contributes nothing). ``increase`` is the sum of those deltas, ``rate``
        that sum divided by the seconds between the window's first and last
        sample. Only samples actually inside the window are used: no boundary
        borrowing, no interpolation, no extrapolation. A window with fewer
        than two distinct sample timestamps yields ``None``; unchanged readings
        yield zero. Grouped queries compute each series independently and then
        sum the non-``None`` per-series results of the group (never
        differencing across series); a group whose series are all ``None`` at
        a time yields ``None`` there. Any matched sample that actually falls
        into an output window and is negative or non-finite fails the whole
        query with ``ObsError``; samples outside every window or filtered out
        by labels/matchers are never inspected.
        """
        # Compile before anything else so all matchers are validated even when
        # another argument (or the absence of candidate series) would yield an
        # empty result.
        compiled_matchers = compile_matchers(matchers)
        if agg is not None and agg not in AGGREGATES + COUNTER_AGGREGATES:
            raise ObsError("unknown aggregation: %r" % (agg,))
        if agg in COUNTER_AGGREGATES and window_ms is None:
            raise ObsError("aggregation %r requires window_ms" % (agg,))
        if window_ms is not None:
            lo, hi, step, window = self._window_params(
                start_ms, end_ms, step_ms, window_ms, agg)
            return self._query_windows(tenant, metric, labels, lo, hi, step,
                                       agg, group_by, window, compiled_matchers)
        if step_ms is not None and (not _num(step_ms) or int(step_ms) <= 0):
            raise ObsError("step_ms must be a positive number")
        lo = None if start_ms is None else int(start_ms)
        hi = None if end_ms is None else int(end_ms)
        if lo is not None and hi is not None and hi < lo:
            raise ObsError("end_ms must be >= start_ms")
        if group_by is not None:
            return self._query_grouped(tenant, metric, labels, lo, hi,
                                       step_ms, agg, group_by, compiled_matchers)
        out = []
        for sid, samples in self._samples_for(tenant, metric, labels,
                                              compiled_matchers):
            rows = [item for item in samples
                    if (lo is None or item[0] >= lo) and (hi is None or item[0] <= hi)]
            points = self._bucket(rows, step_ms, agg, lo, hi)
            if points is None or (not points and agg is not None and step_ms is None):
                continue
            out.append({"series_id": sid, "labels": dict(self._series[sid]["labels"]),
                        "points": points})
        return out

    @staticmethod
    def _window_params(start_ms, end_ms, step_ms, window_ms, agg):
        """Validate sliding-window arguments; return ``(start, end, step, window)``."""
        if not isinstance(window_ms, int) or isinstance(window_ms, bool) or window_ms <= 0:
            raise ObsError("window_ms must be a positive integer")
        if not isinstance(start_ms, int) or isinstance(start_ms, bool):
            raise ObsError("sliding-window query requires an integer start_ms")
        if not isinstance(end_ms, int) or isinstance(end_ms, bool):
            raise ObsError("sliding-window query requires an integer end_ms")
        if not isinstance(step_ms, int) or isinstance(step_ms, bool) or step_ms <= 0:
            raise ObsError("sliding-window query requires a positive integer step_ms")
        if end_ms < start_ms:
            raise ObsError("end_ms must be >= start_ms")
        if agg is None:
            raise ObsError("sliding-window query requires agg")
        return start_ms, end_ms, step_ms, window_ms

    def _window_grid(self, start_ms, end_ms, step_ms):
        """The ``start_ms + k*step_ms`` evaluation times not past ``end_ms``."""
        return range(start_ms, end_ms + 1, step_ms)

    def _window_values(self, rows, window, times, agg):
        """Aggregate the samples of ``(t - window, t]`` for each ``t``.

        ``rows`` is a timestamp-sorted sample list shared by every time. A
        sample at the evaluation time is included; one exactly one window
        length earlier is excluded. Empty windows (no samples, regardless of
        the aggregation, even ``count``) become ``None``.
        """
        points = []
        index = 0
        for t in times:
            left = t - window
            while index < len(rows) and rows[index][0] <= left:
                index += 1
            values = []
            for cursor in range(index, len(rows)):
                stamp = rows[cursor][0]
                if stamp > t:
                    break
                values.append(rows[cursor][1])
            points.append([t, None if not values else _aggregate(values, agg)])
        return points

    @staticmethod
    def _counter_value(windowed, agg):
        """``increase``/``rate`` of one series over one window's samples.

        ``windowed`` is the timestamp-sorted samples of a single series inside
        ``(t - window, t]``. Every sample actually in the window must be a
        non-negative finite number, else the whole query fails. Fewer than two
        samples (hence fewer than two distinct timestamps) yield ``None``.
        """
        for stamp, value in windowed:
            if not math.isfinite(value) or value < 0:
                raise ObsError(
                    "aggregation %r requires non-negative finite samples, "
                    "got %r at timestamp %d" % (agg, value, stamp))
        if len(windowed) < 2:
            return None
        total = 0.0
        previous = windowed[0][1]
        for _, value in windowed[1:]:
            # A drop means the counter reset: count only the later reading.
            total += value - previous if value >= previous else value
            previous = value
        if agg == "increase":
            return total
        span_seconds = (windowed[-1][0] - windowed[0][0]) / 1000.0
        return total / span_seconds

    def _window_counter_points(self, rows, window, times, agg):
        """Per-time ``increase``/``rate`` for one series over the time grid."""
        points = []
        index = 0
        for t in times:
            left = t - window
            while index < len(rows) and rows[index][0] <= left:
                index += 1
            windowed = []
            for cursor in range(index, len(rows)):
                stamp = rows[cursor][0]
                if stamp > t:
                    break
                windowed.append(rows[cursor])
            points.append([t, self._counter_value(windowed, agg)])
        return points

    def _query_windows(self, tenant, metric, labels, lo, hi, step_ms, agg,
                       group_by, window, compiled_matchers=()):
        if group_by is not None:
            if not isinstance(group_by, (list, tuple)):
                raise ObsError("group_by must be a list of label keys")
            keys = list(group_by)
            for key in keys:
                if not isinstance(key, str) or not key:
                    raise ObsError("group_by entries must be non-empty strings")
            if len(set(keys)) != len(keys):
                raise ObsError("group_by entries must not contain duplicates")
        times = list(self._window_grid(lo, hi, step_ms))
        matched = self._matching_series(tenant, metric, labels, compiled_matchers)
        counter = agg in COUNTER_AGGREGATES
        if group_by is None:
            out = []
            for sid, series_labels, samples in matched:
                if counter:
                    points = self._window_counter_points(samples, window, times, agg)
                else:
                    points = self._window_values(samples, window, times, agg)
                out.append({"series_id": sid, "labels": dict(series_labels),
                            "points": points})
            return out
        groups = {}
        for sid, series_labels, samples in matched:
            group_labels = {key: series_labels[key] for key in keys
                            if key in series_labels}
            token = tuple(sorted(group_labels.items()))
            entry = groups.setdefault(token, {"labels": group_labels, "rows": []})
            # The first window reads history before start_ms; no window reads
            # anything past its own evaluation time, so no upper filter applies.
            if counter:
                # Counter aggregates are computed per series, never across
                # series; the group sums the per-series results afterwards.
                entry["rows"].append(
                    self._window_counter_points(samples, window, times, agg))
            else:
                entry["rows"].extend(samples)
        out = []
        for token in sorted(groups):
            entry = groups[token]
            if counter:
                points = []
                for position, t in enumerate(times):
                    values = [column[position][1] for column in entry["rows"]
                              if column[position][1] is not None]
                    points.append([t, sum(values) if values else None])
            else:
                rows = sorted(entry["rows"])
                points = self._window_values(rows, window, times, agg)
            out.append({"labels": entry["labels"], "points": points})
        return out

    def _bucket(self, rows, step_ms, agg, lo, hi):
        """``None`` = nothing to report, ``[]`` = known empty, else the points."""
        if step_ms is None:
            if agg is None:
                return [[stamp, value] for stamp, value in rows]
            return None if not rows else [[rows[0][0], _aggregate([v for _, v in rows], agg)]]
        step = int(step_ms)
        groups = {}
        for stamp, value in rows:
            groups.setdefault(stamp - (stamp % step), []).append(value)
        if not groups:
            return None
        keys = sorted(groups)
        start = max(keys[0], lo - (lo % step)) if lo is not None else keys[0]
        end = min(keys[-1], hi - (hi % step)) if hi is not None else keys[-1]
        return [[key, _aggregate(groups[key], agg) if key in groups else None]
                for key in range(start, end + 1, step)]

    def _query_grouped(self, tenant, metric, labels, lo, hi, step_ms, agg, group_by,
                       compiled_matchers=()):
        """Cross-series aggregation: one row per distinct ``group_by`` tuple.

        The raw in-range samples of every series in a group are pooled before
        aggregating (no per-series pre-averaging), so samples from different
        series at the same timestamp each count. A group key absent from a
        series simply does not appear in that group's labels; a missing key
        and an empty-string value therefore land in different groups.
        """
        if not isinstance(group_by, (list, tuple)):
            raise ObsError("group_by must be a list of label keys")
        keys = list(group_by)
        for key in keys:
            if not isinstance(key, str) or not key:
                raise ObsError("group_by entries must be non-empty strings")
        if len(set(keys)) != len(keys):
            raise ObsError("group_by entries must not contain duplicates")
        if agg is None:
            raise ObsError("group_by requires agg")
        groups = {}
        for sid, samples in self._samples_for(tenant, metric, labels,
                                              compiled_matchers):
            series_labels = dict(self._series[sid]["labels"])
            group_labels = {key: series_labels[key] for key in keys
                            if key in series_labels}
            token = tuple(sorted(group_labels.items()))
            entry = groups.setdefault(token, {"labels": group_labels, "rows": []})
            entry["rows"].extend(item for item in samples
                                 if (lo is None or item[0] >= lo)
                                 and (hi is None or item[0] <= hi))
        out = []
        for token in sorted(groups):
            entry = groups[token]
            rows = sorted(entry["rows"])
            if step_ms is None:
                points = [] if not rows else \
                    [[rows[0][0], _aggregate([value for _, value in rows], agg)]]
            else:
                points = self._bucket(rows, step_ms, agg, lo, hi) or []
            out.append({"labels": entry["labels"], "points": points})
        return out

    def rollup(self, tenant, metric, labels, window_ms, agg):
        """Downsampled series over the whole stored range, ordered by series_id."""
        if agg not in AGGREGATES:
            raise ObsError("unknown aggregation: %r" % (agg,))
        if not _num(window_ms) or int(window_ms) <= 0:
            raise ObsError("window_ms must be a positive number")
        return [{"series_id": item["series_id"], "labels": item["labels"],
                 "points": [point for point in item["points"] if point[1] is not None]}
                for item in self.query(tenant, metric, labels=labels,
                                       step_ms=int(window_ms), agg=agg)]

    # --------------------------------------------------------------- retention
    def _load_retention(self):
        """Reload ``retention.json``; a missing file means no tenant has a policy."""
        if not os.path.exists(self.retention_path):
            return
        try:
            with open(self.retention_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, ValueError) as exc:
            raise ObsError("cannot read retention config: %s" % exc)
        if not isinstance(data, dict):
            raise ObsError("cannot read retention config: root must be an object")
        for tenant, row in data.items():
            if not isinstance(tenant, str) or not tenant or not isinstance(row, dict):
                raise ObsError("cannot read retention config: malformed entry")
            self._retention[tenant] = self._clean_retention_ms(row.get("retention_ms"))

    @staticmethod
    def _clean_retention_ms(value):
        """A retention policy is a non-negative integer of ms or ``None`` (keep all)."""
        if value is None:
            return None
        if isinstance(value, bool) or not isinstance(value, int):
            raise ObsError("retention_ms must be a non-negative integer or null")
        if value < 0:
            raise ObsError("retention_ms must be a non-negative integer or null")
        return value

    def _save_retention(self):
        _atomic_write(self.retention_path, json.dumps(
            {tenant: {"retention_ms": self._retention[tenant]}
             for tenant in sorted(self._retention)},
            sort_keys=True, separators=(",", ":")))

    def set_retention(self, tenant, retention_ms):
        """Configure the tenant's retention policy; ``None`` means no cleanup.

        The policy is persisted and never creates a series. Returns the
        normalised policy together with the tenant's live series/point usage.
        """
        tenant = self._clean_tenant(tenant)
        retention_ms = self._clean_retention_ms(retention_ms)
        with self._lock:
            self._retention[tenant] = retention_ms
            self._save_retention()
            return self.get_retention(tenant)

    def get_retention(self, tenant):
        """The tenant's policy plus its live series/point usage in one snapshot.

        An unconfigured tenant reports a ``null`` policy with its real usage.
        """
        tenant = self._clean_tenant(tenant)
        with self._lock:
            series = points = 0
            for sid, row in self._series.items():
                if row["tenant"] == tenant:
                    series += 1
                    points += len(self._samples[sid])
            return {"tenant": tenant, "retention_ms": self._retention.get(tenant),
                    "series": series, "points": points}

    def _needs_compaction(self, sid, keep):
        """True when the point file of ``sid`` is not the canonical compacted
        form of ``keep`` (duplicate timestamp lines, junk lines, drift)."""
        path = self._points_path(sid)
        if not os.path.exists(path):
            return bool(keep)
        rows = {}
        lines = 0
        try:
            with open(path, "r", encoding="utf-8") as handle:
                for line in handle:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        row = json.loads(line)
                        rows[int(row["t"])] = float(row["v"])
                        lines += 1
                    except (ValueError, KeyError, TypeError):
                        return True
        except OSError:
            return False
        if lines != len(rows):
            return True
        return sorted(rows.items()) != [tuple(item) for item in keep]

    def run_retention(self, now_ms, tenant=None, dry_run=False):
        """Apply the configured retention policies as of ``now_ms``.

        ``now_ms`` must be a non-boolean integer. With ``tenant`` given only
        that tenant is processed; otherwise every tenant with a configured
        policy is processed in lexicographic order. For each tenant the cutoff
        is ``now_ms - retention_ms`` and only samples with
        ``timestamp_ms < cutoff_ms`` are dropped (a sample exactly at the
        cutoff is kept); a ``null`` policy cleans nothing and reports a
        ``null`` cutoff with zero deletions. Affected point files are rewritten
        in compacted form — one physical record per timestamp, the final value
        winning — and empty series stay registered. The freed points count
        against the tenant's quota immediately.

        The whole run is one atomic step: concurrent queries, quota and stats
        reads only ever see the complete state before or after it. With
        ``dry_run=True`` the same report is produced but memory, files, quotas
        and the write counter are left untouched. Returns
        ``{"dry_run": bool, "tenants": [...]}`` with one
        ``{"tenant", "cutoff_ms", "dropped", "affected_series",
        "remaining_points", "compacted_series"}`` entry per processed tenant,
        in lexicographic tenant order.
        """
        if isinstance(now_ms, bool) or not isinstance(now_ms, int):
            raise ObsError("now_ms must be a non-boolean integer timestamp in ms")
        if tenant is not None:
            tenant = self._clean_tenant(tenant)
        if not isinstance(dry_run, bool):
            raise ObsError("dry_run must be a boolean")
        with self._lock:
            names = [tenant] if tenant is not None else sorted(self._retention)
            results = []
            for name in names:
                policy = self._retention.get(name)
                sids = sorted(sid for sid, row in self._series.items()
                              if row["tenant"] == name)
                if policy is None:
                    results.append({
                        "tenant": name, "cutoff_ms": None, "dropped": 0,
                        "affected_series": 0,
                        "remaining_points":
                            sum(len(self._samples[sid]) for sid in sids),
                        "compacted_series": 0})
                    continue
                cutoff = now_ms - policy
                dropped = affected = compacted = remaining = 0
                for sid in sids:
                    keep = [item for item in self._samples[sid]
                            if item[0] >= cutoff]
                    removed = len(self._samples[sid]) - len(keep)
                    if removed:
                        affected += 1
                        dropped += removed
                    remaining += len(keep)
                    if removed or self._needs_compaction(sid, keep):
                        compacted += 1
                        if not dry_run:
                            self._samples[sid] = keep
                            self._rewrite_points(sid)
                results.append({"tenant": name, "cutoff_ms": cutoff,
                                "dropped": dropped, "affected_series": affected,
                                "remaining_points": remaining,
                                "compacted_series": compacted})
            return {"dry_run": dry_run, "tenants": results}

    def enforce_retention(self, tenant, cutoff_ms):
        """Drop every sample with ``timestamp_ms < cutoff_ms`` for ``tenant``."""
        cutoff = int(cutoff_ms)
        dropped = affected = 0
        with self._lock:
            for sid in sorted(self._series):
                if self._series[sid]["tenant"] != tenant:
                    continue
                keep = [item for item in self._samples[sid] if item[0] >= cutoff]
                removed = len(self._samples[sid]) - len(keep)
                if removed:
                    self._samples[sid] = keep
                    self._rewrite_points(sid)
                    dropped += removed
                    affected += 1
        return {"dropped": dropped, "series": affected, "cutoff_ms": cutoff}

    def stats(self):
        with self._lock:
            per_tenant = {}
            points = 0
            for sid, row in self._series.items():
                count = len(self._samples[sid])
                points += count
                entry = per_tenant.setdefault(row["tenant"], {"series": 0, "points": 0})
                entry["series"] += 1
                entry["points"] += count
        return {"series": len(self._series), "points": points, "writes": self._writes,
                "tenants": per_tenant}

"""obsd.alerts - rules, evaluation, silence/inhibition, dedup and SLO math.

All time is injected through ``now_ms``; nothing here reads the wall clock.
"""

from __future__ import annotations

import copy
import json
import os
import threading

from .tsdb import ObsError, _atomic_write, _labels_list, matches_labels

__all__ = ["AlertEngine", "COMPARATORS", "AGGREGATES", "SEVERITIES", "STATE_FIRING",
           "STATE_SILENCED", "STATE_INHIBITED", "STATE_RESOLVED", "EVENTS"]
COMPARATORS = (">", ">=", "<", "<=", "==", "!=")
AGGREGATES = ("sum", "avg", "min", "max", "count")
SEVERITIES = ("info", "warning", "critical")
SEVERITY_RANK = {"info": 1, "warning": 2, "critical": 3}
STATE_FIRING = "firing"
STATE_SILENCED = "silenced"
STATE_INHIBITED = "inhibited"
STATE_RESOLVED = "resolved"
ACTIVE_STATES = (STATE_FIRING, STATE_SILENCED, STATE_INHIBITED)
EVENTS = ("firing", "resolved")
_FILES = ("rules", "alerts", "slos", "silences", "inhibitions", "counters",
          "routes", "notifications", "notify_state")


def _is_num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)
def _require_int(value, field):
    if not _is_num(value) or int(value) != value:
        raise ObsError("%s must be an integer" % field)
    return int(value)
def compare(value, comparator, threshold):
    """Apply ``comparator`` to a bucket value; ``None`` never satisfies."""
    if value is None:
        return False
    if comparator == ">":
        return value > threshold
    if comparator == ">=":
        return value >= threshold
    if comparator == "<":
        return value < threshold
    if comparator == "<=":
        return value <= threshold
    if comparator == "==":
        return value == threshold
    if comparator == "!=":
        return value != threshold
    raise ObsError("unknown comparator: %r" % (comparator,))
class AlertEngine:
    """Rule evaluation with dedup, silences, inhibition and SLO tracking.

    Persisted under ``root`` as rules.json, alerts.json, slos.json,
    silences.json, inhibitions.json, counters.json, routes.json,
    notifications.json and notify_state.json (atomic writes); a new
    instance reloads all of it, so alerts and rules survive a restart.
    """

    def __init__(self, store, root):
        if store is None:
            raise ObsError("store is required")
        if not isinstance(root, (str, os.PathLike)) or not str(root):
            raise ObsError("root must be a non-empty path")
        self.store = store
        self.root = os.path.abspath(str(root))
        self._lock = threading.RLock()
        self._rules, self._silences, self._inhibitions, self._slos, self._alerts = {}, {}, {}, {}, {}
        self._routes, self._notifications, self._notify_state = {}, {}, {}
        self._counters = {"rule": 0, "silence": 0, "inhibition": 0, "alert": 0,
                          "route": 0, "notification": 0}
        os.makedirs(self.root, exist_ok=True)
        self._load()
    # ------------------------------------------------------------- persistence
    def _path(self, name):
        return os.path.join(self.root, name + ".json")
    def _read(self, name, default):
        path = self._path(name)
        if not os.path.exists(path):
            return default
        try:
            with open(path, "r", encoding="utf-8") as handle:
                return json.load(handle)
        except (OSError, ValueError) as exc:
            raise ObsError("cannot read %s.json: %s" % (name, exc))
    def _write(self, name, rows):
        _atomic_write(self._path(name), json.dumps(rows, sort_keys=True, separators=(",", ":")))
    def _dump(self, name, mapping):
        self._write(name, [mapping[key] for key in sorted(mapping)])
    def _load(self):
        rules = self._read("rules", [])
        for rule in rules.values() if isinstance(rules, dict) else rules:
            self._rules[rule["id"]] = rule
        for row in self._read("silences", []):
            self._silences[row["id"]] = row
        for row in self._read("inhibitions", []):
            self._inhibitions[row["id"]] = row
        for row in self._read("slos", []):
            self._slos[(row["tenant"], row["name"])] = row
        for row in self._read("alerts", []):
            row["firing"] = bool(row.get("firing")) and row.get("state") != STATE_RESOLVED
            self._alerts[(row["rule_id"], row["series_id"])] = row
        for row in self._read("routes", []):
            self._routes[row["id"]] = row
        for row in self._read("notifications", []):
            self._notifications[row["id"]] = row
        for row in self._read("notify_state", []):
            self._notify_state[(row["route_id"], row["alert_id"])] = {
                "firing": bool(row.get("firing")), "last_ms": row.get("last_ms")}
        for key, value in self._read("counters", {}).items():
            if key in self._counters:
                self._counters[key] = max(int(value), self._counters[key])
    # ------------------------------------------------------------------ rules
    def add_rule(self, rule):
        """Validate and store a rule; ``id`` is generated when omitted."""
        if not isinstance(rule, dict):
            raise ObsError("rule must be an object")
        with self._lock:
            self._counters["rule"] += 1
            rid = rule.get("id") or "rule-%04d" % self._counters["rule"]
            clean = self._validate(rule, rid)
            self._rules[rid] = clean
            self._dump("rules", self._rules)
        return copy.deepcopy(clean)
    def _validate(self, rule, rid):
        if not isinstance(rid, str) or not rid:
            raise ObsError("rule id must be a non-empty string")
        for field in ("tenant", "metric"):
            if not isinstance(rule.get(field), str) or not rule[field]:
                raise ObsError("rule %s must be a non-empty string" % field)
        for field, allowed in (("comparator", COMPARATORS), ("agg", AGGREGATES),
                               ("severity", SEVERITIES)):
            if rule.get(field) not in allowed:
                raise ObsError("rule %s must be one of %s" % (field, allowed))
        if not _is_num(rule.get("threshold")):
            raise ObsError("rule threshold must be a number")
        window = _require_int(rule.get("window_ms"), "rule window_ms")
        if window <= 0:
            raise ObsError("rule window_ms must be positive")
        hold = _require_int(rule.get("for_ms", 0), "rule for_ms")
        if hold < 0:
            raise ObsError("rule for_ms must be >= 0")
        annotations = rule.get("annotations") or {}
        if not isinstance(annotations, dict):
            raise ObsError("rule annotations must be an object")
        return {"id": rid, "tenant": rule["tenant"], "metric": rule["metric"],
                "labels": _labels_list(rule.get("labels")), "comparator": rule["comparator"],
                "threshold": float(rule["threshold"]), "for_ms": hold, "window_ms": window,
                "agg": rule["agg"], "severity": rule["severity"],
                "annotations": {str(k): str(v) for k, v in annotations.items()},
                "error": rule.get("error")}
    def list_rules(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._rules[key]) for key in sorted(self._rules)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def del_rule(self, rule_id):
        with self._lock:
            if rule_id not in self._rules:
                raise ObsError("unknown rule: %s" % rule_id)
            del self._rules[rule_id]
            self._dump("rules", self._rules)
        return {"deleted": rule_id}
    # --------------------------------------------------------------- silences
    def add_silence(self, tenant, matcher_labels, starts_ms, ends_ms, reason=""):
        """Record a silence window; it suppresses matching alerts inside it."""
        if not isinstance(tenant, str) or not tenant:
            raise ObsError("silence tenant must be a non-empty string")
        start = _require_int(starts_ms, "silence starts_ms")
        end = _require_int(ends_ms, "silence ends_ms")
        if end <= start:
            raise ObsError("silence ends_ms must be greater than starts_ms")
        with self._lock:
            self._counters["silence"] += 1
            row = {"id": "silence-%04d" % self._counters["silence"], "tenant": tenant,
                   "labels": _labels_list(matcher_labels), "starts_ms": start,
                   "ends_ms": end, "reason": str(reason or "")}
            self._silences[row["id"]] = row
            self._dump("silences", self._silences)
        return copy.deepcopy(row)
    def list_silences(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._silences[key]) for key in sorted(self._silences)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def _active_silence(self, tenant, labels, now_ms):
        for key in sorted(self._silences):
            row = self._silences[key]
            if row["tenant"] == tenant and row["starts_ms"] <= now_ms <= row["ends_ms"] \
                    and matches_labels(labels, dict(row["labels"])):
                return row
        return None
    # ------------------------------------------------------------- inhibition
    def add_inhibition(self, source_severity, target_severity, same_labels=True):
        """Higher-severity firing alerts suppress matching lower-severity ones."""
        for field, value in (("source_severity", source_severity),
                             ("target_severity", target_severity)):
            if value not in SEVERITIES:
                raise ObsError("%s must be one of %s" % (field, SEVERITIES))
        if SEVERITY_RANK[source_severity] <= SEVERITY_RANK[target_severity]:
            raise ObsError("source_severity must be strictly higher than target_severity")
        if not isinstance(same_labels, bool):
            raise ObsError("same_labels must be a boolean")
        with self._lock:
            self._counters["inhibition"] += 1
            row = {"id": "inhibition-%04d" % self._counters["inhibition"],
                   "source_severity": source_severity, "target_severity": target_severity,
                   "same_labels": same_labels}
            self._inhibitions[row["id"]] = row
            self._dump("inhibitions", self._inhibitions)
        return copy.deepcopy(row)
    def list_inhibitions(self):
        with self._lock:
            return [copy.deepcopy(self._inhibitions[key]) for key in sorted(self._inhibitions)]
    def _inhibited(self, severity, tenant, labels, rule_id, series_id):
        """Id of the firing alert that inhibits this one, or None.

        Equal label sets (the empty set included) are required when
        ``same_labels`` is set; otherwise the source set must be a subset.
        """
        wanted = frozenset((key, str(value)) for key, value in labels.items())
        rules = [row for row in self._inhibitions.values() if row["target_severity"] == severity]
        if not rules:
            return None
        for key in sorted(self._alerts):
            other = self._alerts[key]
            if other["state"] != STATE_FIRING or other["tenant"] != tenant:
                continue
            if (other["rule_id"], other["series_id"]) == (rule_id, series_id):
                continue
            other_labels = frozenset((k, str(v)) for k, v in other["labels"].items())
            for row in rules:
                if SEVERITY_RANK[other["severity"]] < SEVERITY_RANK[row["source_severity"]]:
                    continue
                if other_labels == wanted or (not row["same_labels"] and other_labels <= wanted):
                    return other["id"]
        return None
    # -------------------------------------------------------- notification routes
    def add_route(self, route):
        """Validate and store a notification route; ``id`` is generated when omitted."""
        if not isinstance(route, dict):
            raise ObsError("route must be an object")
        with self._lock:
            clean = self._validate_route(route)
            rid = clean["id"]
            if rid is None:
                while True:
                    self._counters["route"] += 1
                    rid = "route-%04d" % self._counters["route"]
                    if rid not in self._routes:
                        break
                clean["id"] = rid
            elif rid in self._routes:
                raise ObsError("conflict: route id already exists: %s" % rid)
            self._routes[rid] = clean
            self._dump("routes", self._routes)
        return copy.deepcopy(clean)
    def _validate_route(self, route):
        rid = route.get("id")
        if rid is not None and (not isinstance(rid, str) or not rid):
            raise ObsError("route id must be a non-empty string")
        for field in ("tenant", "target"):
            if not isinstance(route.get(field), str) or not route[field]:
                raise ObsError("route %s must be a non-empty string" % field)
        severities = self._route_choice(route.get("severities"), SEVERITIES, "severities")
        events = self._route_choice(route.get("events"), EVENTS, "events")
        repeat = route.get("repeat_ms")
        if repeat is not None:
            repeat = _require_int(repeat, "route repeat_ms")
            if repeat < 0:
                raise ObsError("route repeat_ms must be >= 0")
        return {"id": rid, "tenant": route["tenant"], "target": route["target"],
                "labels": _labels_list(route.get("labels")), "severities": severities,
                "events": events, "repeat_ms": repeat}
    @staticmethod
    def _route_choice(value, allowed, field):
        """A route selector: absent means all of ``allowed``; otherwise a non-empty
        array of allowed values, normalised to ``allowed`` order without duplicates."""
        if value is None:
            return list(allowed)
        if not isinstance(value, list) or not value:
            raise ObsError("route %s must be a non-empty array" % field)
        for item in value:
            if item not in allowed:
                raise ObsError("route %s must be one of %s" % (field, allowed))
        return [item for item in allowed if item in value]
    def list_routes(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._routes[key]) for key in sorted(self._routes)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def del_route(self, route_id):
        """Delete a route; its historical notifications are kept."""
        with self._lock:
            if route_id not in self._routes:
                raise ObsError("unknown route: %s" % route_id)
            del self._routes[route_id]
            self._dump("routes", self._routes)
        return {"deleted": route_id}
    # ------------------------------------------------------------- notifications
    def _matching_routes(self, alert):
        return [self._routes[rid] for rid in sorted(self._routes)
                if self._routes[rid]["tenant"] == alert["tenant"]
                and alert["severity"] in self._routes[rid]["severities"]
                and matches_labels(alert["labels"], dict(self._routes[rid]["labels"]))]
    def _route_event(self, alert, kind, now):
        """Apply one alert transition to every matching route's dedup state.

        ``kind`` is ``"firing"`` (alert is firing), ``"resolved"`` (alert just
        resolved) or ``None`` (pending, silenced or inhibited: no notification,
        and the firing episode ends so a later recovery re-notifies).
        """
        for route in self._matching_routes(alert):
            key = (route["id"], alert["id"])
            state = self._notify_state.get(key)
            if kind is None:
                if state is not None:
                    state["firing"] = False
                continue
            if state is None:
                state = self._notify_state[key] = {"firing": False, "last_ms": None}
            if kind == "firing":
                if "firing" in route["events"]:
                    if not state["firing"]:
                        self._emit_notification(route, alert, "firing", now)
                        state["last_ms"] = now
                    elif route["repeat_ms"] is not None and state["last_ms"] is not None \
                            and now - state["last_ms"] >= route["repeat_ms"]:
                        self._emit_notification(route, alert, "firing", now)
                        state["last_ms"] = now
                state["firing"] = True
            else:  # resolved: exactly once per resolution
                if "resolved" in route["events"]:
                    self._emit_notification(route, alert, "resolved", now)
                state["firing"] = False
    def _emit_notification(self, route, alert, event, now):
        self._counters["notification"] += 1
        row = {"id": "notification-%05d" % self._counters["notification"],
               "route_id": route["id"], "alert_id": alert["id"],
               "tenant": route["tenant"], "target": route["target"], "event": event,
               "created_ms": now, "alert": copy.deepcopy(alert), "acked": False}
        self._notifications[row["id"]] = row
    def _save_notify_state(self):
        self._write("notify_state",
                    [{"route_id": key[0], "alert_id": key[1],
                      "firing": state["firing"], "last_ms": state["last_ms"]}
                     for key, state in sorted(self._notify_state.items())])
    def list_notifications(self, tenant=None, route_id=None, alert_id=None, acked=None):
        """Filtered read of the notification queue; never consumes entries."""
        with self._lock:
            rows = [copy.deepcopy(self._notifications[key]) for key in sorted(self._notifications)]
        return [row for row in rows
                if (tenant is None or row["tenant"] == tenant)
                and (route_id is None or row["route_id"] == route_id)
                and (alert_id is None or row["alert_id"] == alert_id)
                and (acked is None or row["acked"] == acked)]
    def ack_notification(self, notification_id):
        """Mark a notification acknowledged; re-acking returns the same record."""
        with self._lock:
            row = self._notifications.get(notification_id)
            if row is None:
                raise ObsError("unknown notification: %s" % notification_id)
            if not row["acked"]:
                row["acked"] = True
                self._dump("notifications", self._notifications)
            return copy.deepcopy(row)
    # --------------------------------------------------------------- evaluate
    def _condition(self, rule, series_id, now_ms):
        """Buckets of one series inside the rule window, plus the hold decision.

        The window is ``[bucket_start(now_ms) - window_ms, now_ms]`` with
        ``bucket_start(t) = t - (t % window_ms)``: the running bucket plus the
        whole previous one. The condition holds when every non-empty bucket in
        the window satisfies the comparator; ``held_ms`` spans the unbroken run
        of satisfying buckets ending at the last bucket.
        """
        step = rule["window_ms"]
        buckets = labels = None
        for item in self.store.query(
                rule["tenant"], rule["metric"], labels=dict(rule["labels"]),
                start_ms=now_ms - (now_ms % step) - step, end_ms=now_ms,
                step_ms=step, agg=rule["agg"]):
            if item["series_id"] == series_id:
                buckets, labels = item["points"], item["labels"]
                break
        values = [point[1] for point in buckets or [] if point[1] is not None]
        if not values:
            return None
        satisfied = [compare(value, rule["comparator"], rule["threshold"]) for value in values]
        if not all(satisfied):
            return {"hold": False, "labels": labels, "observed": values[-1]}
        run = 0
        for index in range(len(satisfied) - 1, -1, -1):
            if not satisfied[index]:
                run = index + 1
                break
        held = int(buckets[-1][0]) - int(buckets[run][0])
        return {"hold": True, "labels": labels, "observed": values[-1],
                "run_start": int(buckets[run][0]), "held_ms": held,
                "for_satisfied": held >= rule["for_ms"]}
    def evaluate(self, now_ms):
        """Evaluate every rule at ``now_ms`` -> firing/silenced/inhibited/resolved."""
        now = _require_int(now_ms, "now_ms")
        out = {STATE_FIRING: [], STATE_SILENCED: [], STATE_INHIBITED: [], STATE_RESOLVED: []}
        with self._lock:
            for rule in self.list_rules():
                if rule.get("error"):
                    raise ObsError("cannot evaluate rule %s: %s" % (rule["id"], rule["error"]))
                step = rule["window_ms"]
                for sid, _ in self.store._scan(
                        rule["tenant"], rule["metric"], dict(rule["labels"]),
                        now - (now % step) - step, now):
                    state = self._condition(rule, sid, now)
                    if state is None:
                        continue
                    key = (rule["id"], sid)
                    alert = self._alerts.get(key)
                    if not state["hold"]:
                        if alert is not None and alert["state"] in ACTIVE_STATES:
                            alert.update(state=STATE_RESOLVED, firing=False, resolved_ms=now)
                            out[STATE_RESOLVED].append(copy.deepcopy(alert))
                            self._route_event(alert, "resolved", now)
                        continue
                    if alert is None:
                        alert = {"id": self._next_alert_id(), "rule_id": rule["id"],
                                 "tenant": rule["tenant"], "metric": rule["metric"],
                                 "series_id": sid, "labels": dict(state["labels"]),
                                 "severity": rule["severity"], "occurrences": 0,
                                 "annotations": copy.deepcopy(rule["annotations"]),
                                 "state": STATE_FIRING}
                        self._alerts[key] = alert
                    alert.update(occurrences=int(alert.get("occurrences", 0)) + 1, firing=True,
                                 since_ms=state["run_start"], last_eval_ms=now,
                                 observed=state["observed"], held_ms=state["held_ms"])
                    if not state["for_satisfied"]:
                        self._route_event(alert, None, now)
                        continue
                    silence = self._active_silence(rule["tenant"], state["labels"], now)
                    blocker = None if silence else self._inhibited(
                        alert["severity"], rule["tenant"], state["labels"], rule["id"], sid)
                    if silence is not None:
                        alert.update(state=STATE_SILENCED, silenced_by=silence["id"],
                                     silence_reason=silence["reason"])
                        out[STATE_SILENCED].append(copy.deepcopy(alert))
                        self._route_event(alert, None, now)
                    elif blocker is not None:
                        alert.update(state=STATE_INHIBITED, inhibited_by=blocker)
                        out[STATE_INHIBITED].append(copy.deepcopy(alert))
                        self._route_event(alert, None, now)
                    else:
                        alert.update(state=STATE_FIRING)
                        alert.pop("silenced_by", None)
                        alert.pop("inhibited_by", None)
                        out[STATE_FIRING].append(copy.deepcopy(alert))
                        self._route_event(alert, "firing", now)
            self._write("alerts", [self._alerts[k] for k in
                                   sorted(self._alerts, key=lambda k: (k[0], k[1]))])
            self._dump("notifications", self._notifications)
            self._save_notify_state()
            self._write("counters", self._counters)
        for rows in out.values():
            rows.sort(key=lambda row: row["id"])
        return out
    def _next_alert_id(self):
        self._counters["alert"] += 1
        return "alert-%05d" % self._counters["alert"]
    # ----------------------------------------------------------------- alerts
    def list_alerts(self, tenant=None, state=None):
        with self._lock:
            rows = [copy.deepcopy(self._alerts[key]) for key in sorted(self._alerts)]
        return [row for row in rows
                if (tenant is None or row["tenant"] == tenant)
                and (state is None or row["state"] == state)]
    def get_alert(self, alert_id):
        with self._lock:
            for row in self._alerts.values():
                if row["id"] == alert_id:
                    return copy.deepcopy(row)
        raise ObsError("unknown alert: %s" % alert_id)
    # -------------------------------------------------------------------- SLO
    def set_slo(self, tenant, name, metric, labels, good_comparator, threshold,
                target_ratio, window_ms):
        """Define a good-events ratio SLO over a sliding ``window_ms``."""
        for field, value in (("tenant", tenant), ("name", name), ("metric", metric)):
            if not isinstance(value, str) or not value:
                raise ObsError("slo %s must be a non-empty string" % field)
        if good_comparator not in COMPARATORS:
            raise ObsError("good_comparator must be one of %s" % (COMPARATORS,))
        if not _is_num(threshold):
            raise ObsError("slo threshold must be a number")
        if not _is_num(target_ratio) or not 0.0 < float(target_ratio) <= 1.0:
            raise ObsError("target_ratio must be in (0, 1]")
        window = _require_int(window_ms, "slo window_ms")
        if window <= 0:
            raise ObsError("slo window_ms must be positive")
        row = {"tenant": tenant, "name": name, "metric": metric,
               "labels": _labels_list(labels), "good_comparator": good_comparator,
               "threshold": float(threshold), "target_ratio": float(target_ratio),
               "window_ms": window}
        with self._lock:
            self._slos[(tenant, name)] = row
            self._dump("slos", self._slos)
        return copy.deepcopy(row)
    def _find_slo(self, name, tenant=None):
        with self._lock:
            if tenant is not None and (tenant, name) in self._slos:
                return copy.deepcopy(self._slos[(tenant, name)])
            matches = [self._slos[key] for key in sorted(self._slos) if key[1] == name]
        if not matches:
            raise ObsError("unknown slo: %s" % name)
        if len(matches) > 1 and tenant is None:
            raise ObsError("slo %s exists for several tenants; pass tenant" % name)
        return matches[0]
    def list_slos(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._slos[key]) for key in sorted(self._slos)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def slo_status(self, name, now_ms, tenant=None):
        """Event-ratio SLO status over ``[now_ms - window_ms, now_ms]``.

        Every stored sample in the window is one event: ``total`` counts them,
        ``good`` counts those satisfying the good comparator, ``bad = total -
        good``.

            ratio        = good / total                            (0.0 if total == 0)
            error_budget = max(0, 1 - (1 - ratio) / (1 - target))  (target < 1)
            burn_rate    = (bad / total) / (1 - target)            (0.0 if target >= 1)
            met          = ratio >= target
        """
        now = _require_int(now_ms, "now_ms")
        slo = self._find_slo(name, tenant)
        total = good = 0
        for _, rows in self.store._scan(slo["tenant"], slo["metric"], dict(slo["labels"]),
                                        now - slo["window_ms"], now):
            for _, value in rows:
                total += 1
                if compare(value, slo["good_comparator"], slo["threshold"]):
                    good += 1
        bad = total - good
        target = float(slo["target_ratio"])
        ratio = (good / float(total)) if total else 0.0
        allowed_bad = 1.0 - target
        if allowed_bad > 0.0:
            error_budget = max(0.0, 1.0 - ((1.0 - ratio) / allowed_bad))
        else:
            error_budget = 1.0 if ratio >= 1.0 else 0.0
        burn_rate = ((bad / float(total)) / allowed_bad) if (allowed_bad > 0.0 and total) else 0.0
        return {"tenant": slo["tenant"], "name": slo["name"], "window_ms": slo["window_ms"],
                "total": total, "good": good, "bad": bad, "ratio": ratio,
                "target_ratio": target, "error_budget": error_budget,
                "burn_rate": burn_rate, "met": ratio >= target}

